// app/lib/db.ts

// Simple in-memory storage simulation
export interface Post {
  id: number;
  title: string;
}

let posts: Post[] = [
  { id: 1, title: 'Hello World' },
];

export async function getPosts(): Promise<Post[]> {
  // Simulate network latency
  await new Promise((resolve) => setTimeout(resolve, 100));
  return [...posts]; // Return a copy to avoid reference issues
}

export async function addPost(title: string): Promise<void> {
  // Simulate network latency
  await new Promise((resolve) => setTimeout(resolve, 100));
  posts.push({ id: Date.now(), title });
}

'use server'

import { revalidateTag } from 'next/cache';
import { addPost } from './lib/db';

export async function createPost(formData: FormData) {
  const title = formData.get('title');

  if (!title || typeof title !== 'string') {
    return;
  }

  // Simulate creating the post in the database
  await addPost(title);

  // Invalidate the cache for the 'posts' tag
  // This ensures the next request for data with this tag will be re-fetched
  revalidateTag('posts');
}

import { unstable_cache } from 'next/cache';
import { getPosts } from './lib/db';
import { createPost } from './actions';

// Wrap the database query with unstable_cache to use cache tags
const getCachedPosts = unstable_cache(
  async () => getPosts(),
  ['posts-list'], 
  { tags: ['posts'] }
);

export default async function Home() {
  const posts = await getCachedPosts();

  return (
    <main style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Posts</h1>

      <form action={createPost} style={{ marginBottom: '20px' }}>
        <input 
          type="text" 
          name="title" 
          placeholder="Enter post title" 
          required
          style={{ padding: '8px', marginRight: '10px' }}
        />
        <button type="submit" style={{ padding: '8px 16px' }}>
          Create Post
        </button>
      </form>

      <ul style={{ listStyle: 'none', padding: 0 }}>
        {posts.map((post) => (
          <li key={post.id} style={{ padding: '10px', borderBottom: '1px solid #ccc' }}>
            {post.title}
          </li>
        ))}
      </ul>
    </main>
  );
}

